def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full-height divider.
    divider = next(
        (c for c in range(w) if all(grid[r][c] == 2 for r in range(h))),
        None
    )
    if divider is None:
        return [row[:] for row in grid]

    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if c != divider
    )
    background = counts.most_common(1)[0][0]

    cells = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if c != divider and grid[r][c] != background
    ]
    if not cells:
        return [row[:] for row in grid]

    min_c = min(c for _, c, _ in cells)
    max_c = max(c for _, c, _ in cells)

    if max_c < divider:
        shift = divider - 1 - max_c
    else:
        shift = divider + 1 - min_c

    out = [row[:] for row in grid]
    for r, c, _ in cells:
        out[r][c] = background
    for r, c, color in cells:
        out[r][c + shift] = color

    # Mark the original right edge of the object.
    for r in range(h):
        out[r][max_c] = 8

    return out
